#!/usr/bin/env python3
"""Build the full run-up calendar: 122 daily posts, Aug -> the November event.

Day 122 = event day. The calendar is countdown-relative, so it shifts to whatever
November date the show lands on.

  days 1–7     the offer          (the original opening week)
  days 8–99    the serial         (92 posts, seven recurring formats)
  days 100–122 the countdown      (the original crews/people/games run)
"""
import json
from collections import OrderedDict as O

SRC = '/home/user/showbuilderapp/marketing/daily-transmissions.json'
OUT = SRC
old = json.load(open(SRC))
OLD = {p['day']: p for p in old['posts']}

G, P, C, V, L, S, N = '#f5c542', '#ff2d9b', '#00e5ff', '#a06bff', '#ff5a6e', '#ffd36b', '#8f8fa6'

FORMATS = O([
 ("TRANSMISSION", "TJ straight to camera about the night itself. The offer, the ask, the stakes. The only format that sells."),
 ("CITY RECORDS", "A piece of the fifty-year history. TJ over archive-feel b-roll — no face needed, batch the VO."),
 ("RAP SHEET",    "One character, one file. Name, crew, known for, one story. The most batchable format you have."),
 ("OVERHEARD",    "One line somebody said, then TJ explains what it meant. Shortest format, highest share rate."),
 ("THE DIAL",     "The music. What each crew sounds like and why. Your natural territory — shoot these behind the decks."),
 ("EVIDENCE",     "McGraw's case. A photo, a file, a dead end. This is the format that carries the myth."),
 ("HOUSE RULES",  "Practical. What the night is, what to wear, how it works. Kills objections and drives tickets."),
])

